export const japanesePatterns = [
  [/^第 (\d+) 轨，按键 (.+)$/, (_, n, key) => `レーン${n}、キー ${key}`],
  [/^第 (\d+) 轨$/, (_, n) => `レーン${n}`],
  [/^传说 · (.+) 星$/, (_, n) => `レジェンド · 星${n}`],
  [/^已跳转至 (.+)；本轮完成度从当前位置重新计算。$/, (_, time) => `${time}に移動しました。今回の達成度は現在位置から再計算されます。`],
  [/^上一轮：完成度 (.+)%，命中 (.+) \/ (.+)。继续练习。$/, (_, score, hits, total) => `前回：達成度 ${score}%、ヒット ${hits} / ${total}。練習を続けましょう。`],
  [/^本段练习完成：完成度 (.+)%，命中 (.+) \/ (.+)。$/, (_, score, hits, total) => `練習終了：達成度 ${score}%、ヒット ${hits} / ${total}。`],
  [/^练习区间 (.+)$/, (_, range) => `練習区間 ${range}`],
  [/^判定范围已调整为前后 (.+) ms，已回到片段起点。$/, (_, n) => `判定範囲を前後 ${n} ms に設定し、区間の開始位置に戻りました。`],
  [/^时间偏移已设置为 (.+) ms。正值使判定稍后。$/, (_, n) => `タイミング調整を ${n} ms に設定しました。プラスの値で判定が遅くなります。`],
  [/^音源起点已调整为 (.+) 秒，谱面已回到片段起点。$/, (_, n) => `音源の開始位置を ${n} 秒に設定し、区間の開始位置に戻りました。`],
  [/^已载入本设备保存的音频：(.+)$/, (_, name) => `保存済み音源を読み込みました：${name === '本地音频' ? 'ローカル音源' : name}`],
  [/^已保存在本设备：(.+)$/, (_, name) => `この端末に保存しました：${name}`],
  [/^第 (\d+) 个音符的时间、轨道或时长无效。$/, (_, n) => `${n}番目のノーツの時刻、レーンまたは長さが無効です。`],
  [/^未命中 · (过早|过晚) (\d+) ms$/, (_, kind, n) => `ミス · ${n} ms ${kind === '过早' ? '早い' : '遅い'}`],
  [/^(偏早|偏晚) (\d+) ms$/, (_, kind, n) => `${n} ms ${kind === '偏早' ? '早い' : '遅い'}`],
  [/^曲谱加载失败：(.+)$/, (_, reason, translate) => `譜面を読み込めません：${translate(reason)}`],
  [/^谱面导入失败：(.+)$/, (_, reason, translate) => `譜面の読み込みに失敗しました：${translate(reason)}`],
  [/^在线音源不可用（播放器错误 (\d+)）$/, (_, code) => `オンライン音源を利用できません（プレーヤーエラー ${code}）`],
  [/^(.+)，已切换节拍伴奏；可选择本地音频随原曲练习。$/, (_, reason, translate) => `${translate(reason)}。メトロノームに切り替えました。端末の音源も選択できます。`]
];
